$ErrorActionPreference='Stop'
$cn=New-Object System.Data.Odbc.OdbcConnection('Driver={ODBC Driver 18 for SQL Server};Server=tcp:127.0.0.1,1433;HostnameInCertificate=localhost;Database=master;Trusted_Connection=Yes;Encrypt=Yes;TrustServerCertificate=No;')
try{$cn.Open();$cmd=$cn.CreateCommand();$cmd.CommandText="SELECT collation_name,COALESCE(collation_name,N'<null>') coll_actual,CONVERT(nvarchar(128),DATABASEPROPERTYEX(N'contextbase_test_project1','Collation')) dbproperty FROM sys.databases WHERE name=N'contextbase_test_project1'";$reader=$cmd.ExecuteReader();while($reader.Read()){for($i=0;$i -lt $reader.FieldCount;$i++){[pscustomobject]@{name=$reader.GetName($i);value=[string]$reader.GetValue($i);isNull=$reader.IsDBNull($i);type=$reader.GetDataTypeName($i)}}};$reader.Dispose()}finally{$cn.Dispose()}
